package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
}

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classification string `json:"classification"`
}

// searchDocuments allows full-text search across documents
// NOTE: uses parameterized queries for the search term
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	searchTerm := r.URL.Query().Get("q")
	sortField := r.URL.Query().Get("sort")
	classFilter := r.URL.Query().Get("classification")

	// Validate sort field against allowlist
	allowedSorts := map[string]bool{"title": true, "id": true, "created_at": true}
	if sortField == "" || !allowedSorts[sortField] {
		sortField = "id"
	}

	// Build query with parameterized search but dynamic classification filter
	baseQuery := `SELECT id, title, content, owner_id, classification FROM documents WHERE to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $1)`

	// Classification filter - applied from request parameter
	if classFilter != "" {
		// Developer note: classification values are from a controlled enum,
		// but we concatenate here for flexibility with multi-value filters
		classValues := strings.Split(classFilter, ",")
		quotedValues := make([]string, len(classValues))
		for i, v := range classValues {
			// "Sanitize" by removing single quotes - INSUFFICIENT
			v = strings.ReplaceAll(v, "'", "")
			quotedValues[i] = fmt.Sprintf("'%s'", v)
		}
		baseQuery += " AND classification IN (" + strings.Join(quotedValues, ",") + ")"
	}

	baseQuery += fmt.Sprintf(" ORDER BY %s LIMIT 50", sortField)

	rows, err := db.Query(baseQuery, searchTerm)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classification); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// getDocument retrieves a single document - no ownership check (IDOR)
func getDocument(w http.ResponseWriter, r *http.Request) {
	docID := r.URL.Query().Get("id")
	row := db.QueryRow("SELECT id, title, content, owner_id, classification FROM documents WHERE id = $1", docID)

	var d Document
	if err := row.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classification); err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(d)
}

func main() {
	http.HandleFunc("/api/documents/search", searchDocuments)
	http.HandleFunc("/api/documents/get", getDocument)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
